    logLayout->addWidget(clearLogButton, 0, Qt::AlignRight);
    mainLayout->addWidget(logGroup);

    // Status label
    statusLabel = new QLabel("Ready", this);
    statusLabel->setStyleSheet("QLabel { color: #7f8c8d; font-size: 11px; }");
    mainLayout->addWidget(statusLabel);

    // Connect signals
    connect(browseButton,  &QPushButton::clicked, this, &MainWindow::browseDirectory);
    connect(convertButton, &QPushButton::clicked, this, &MainWindow::startConversion);
    connect(clearLogButton,&QPushButton::clicked, this, &MainWindow::clearLog);
