// ─────────────────────────────────────────────────────────────
void MainWindow::browseDirectory()
{
    QString dir = QFileDialog::getExistingDirectory(
        this,
        "Select Directory",
        QDir::homePath(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (!dir.isEmpty()) {
        selectedDirectory = dir;
        directoryLineEdit->setText(dir);
        convertButton->setEnabled(true);
        logMessage("Directory selected: " + dir, "#2980b9");
    }
}

// ─────────────────────────────────────────────────────────────
void MainWindow::startConversion()
{
    if (selectedDirectory.isEmpty()) {
        QMessageBox::warning(this, "Warning", "Please select a directory first.");
        return;
    }

    // Find all Excel files
    QStringList excelFilters;
    excelFilters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";

    QDirIterator it(selectedDirectory, excelFilters,
                    QDir::Files, QDirIterator::NoIteratorFlags);

    QStringList excelFiles;
    while (it.hasNext()) {
        excelFiles << it.next();
    }

    if (excelFiles.isEmpty()) {
        QMessageBox::information(this, "No Files Found",
            "No Excel files (.xlsx, .xls, .xlsm) were found in the selected directory.");
        return;
    }

    // Create output directory
    QString outputDirName = "CSV_Output_" +
        QDateTime::currentDateTime().toString("yyyyMMdd_HHmmss");
    QString outputDirPath = selectedDirectory + "/" + outputDirName;

    QDir dir;
    if (!dir.mkpath(outputDirPath)) {
        QMessageBox::critical(this, "Error",
            "Failed to create output directory:\n" + outputDirPath);
        return;
    }

    logMessage("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", "#95a5a6");
    logMessage(QString("Found %1 Excel file(s) to convert.").arg(excelFiles.size()), "#2c3e50");
    logMessage("Output directory: " + outputDirPath, "#2980b9");
    logMessage("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", "#95a5a6");

    // Setup progress
    progressBar->setVisible(true);
    progressBar->setMaximum(excelFiles.size());
    progressBar->setValue(0);
    convertButton->setEnabled(false);
    browseButton->setEnabled(false);

    int successCount = 0;
    int failCount    = 0;

    for (int i = 0; i < excelFiles.size(); ++i) {
        const QString &filePath = excelFiles[i];
        QFileInfo fi(filePath);

        logMessage(QString("[%1/%2] Converting: %3")
                   .arg(i + 1).arg(excelFiles.size()).arg(fi.fileName()),
                   "#2c3e50");

        statusLabel->setText(QString("Converting %1...").arg(fi.fileName()));
        QApplication::processEvents();

        if (convertExcelToCsv(filePath, outputDirPath)) {
            logMessage("  ✓ Success", "#27ae60");
            ++successCount;
        } else {
            logMessage("  ✗ Failed", "#e74c3c");
            ++failCount;
        }

        progressBar->setValue(i + 1);
        QApplication::processEvents();
    }

    // Summary
    logMessage("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", "#95a5a6");
    logMessage(QString("Conversion complete! Success: %1  |  Failed: %2")
               .arg(successCount).arg(failCount),
               failCount == 0 ? "#27ae60" : "#e67e22");
    logMessage("CSV files saved to: " + outputDirPath, "#2980b9");

    statusLabel->setText("Conversion complete.");
    convertButton->setEnabled(true);
    browseButton->setEnabled(true);

    QMessageBox::information(this, "Conversion Complete",
        QString("Conversion finished!\n\n"
                "✓ Successful: %1\n"
                "✗ Failed:     %2\n\n"
                "Output folder:\n%3")
        .arg(successCount).arg(failCount).arg(outputDirPath));
}

// ─────────────────────────────────────────────────────────────
bool MainWindow::convertExcelToCsv(const QString &excelFilePath,
                                    const QString &outputDir)
{
    QFileInfo fi(excelFilePath);
    QString ext = fi.suffix().toLower();

#ifdef Q_OS_WIN
    // On Windows, use Excel via COM/ActiveX for best compatibility
    return parseXlsxFile(excelFilePath, outputDir);
#else
    if (ext == "xlsx" || ext == "xlsm") {
        return parseXlsxFile(excelFilePath, outputDir);
    } else if (ext == "xls") {
        logMessage("  ⚠ .xls format requires additional library on non-Windows. "
                   "Skipping.", "#e67e22");
        return false;
    }
    return false;
#endif
}

